// === Tab: grid ===
class Grid {
  constructor(numx, numy, initial = 0) {
    if (!Number.isInteger(numx) || !Number.isInteger(numy) || numx <= 0 || numy <= 0) {
      throw new TypeError("numx/numy must be positive integers");
    }
    this.grid = new Array(numx * numy);
    this.numx = numx;
    this.numy = numy;
    this.initialVal = initial;
    this.init(); // use initialVal
  }

  // Index helper with sanity checks
  getIdx(x, y) {
    if (!Number.isInteger(x) || !Number.isInteger(y)) {
      throw new TypeError(`Indices must be integers: (${x}, ${y})`);
    }
    if (x < 0 || y < 0 || x >= this.numx || y >= this.numy) {
      throw new RangeError(`Out of bounds: (${x}, ${y})`);
    }
    return y * this.numx + x;
  }

  // Clone helper to avoid shared references for arrays/objects
  _clone(v) {
    if (v && typeof v === "object") {
      if (typeof structuredClone === "function") return structuredClone(v);
      return Array.isArray(v) ? v.slice() : { ...v }; // shallow fallback
    }
    return v; // primitives safe
  }

  // Factory initializer support: pass a function for per-cell fresh values
  init(val = this.initialVal) {
    const isFactory = typeof val === "function";
    for (let i = 0; i < this.grid.length; i++) {
      this.grid[i] = isFactory ? val() : this._clone(val);
    }
  }

  setVal(x, y, val) {
    const idx = this.getIdx(x, y);
    const cur = this.grid[idx];
    if (Array.isArray(cur)) {
      cur.push(val); // explicit "append" semantics if cell is an array
    } else {
      this.grid[idx] = this._clone(val); // clone-on-write to avoid sharing
    }
  }

  getVal(x, y) {
    return this.grid[this.getIdx(x, y)];
  }
}


