const NUM_LAYERS = 1;
let S, FG, BG, offX, offY, numX = 3, numY = 4;
let layers, masks;
const { Point, Line, Polygon } = EpiShapeSvg; // external library https://cdn.jsdelivr.net/gh/epibyte/p5-epi-shapesvg@v0.0.15/dist/p5-epi-shapesvg.js

function setup() {
	createCanvas(windowWidth, windowHeight);
	describe("grid of rectangles with randomly rounded edges");
	frameRate(60);
	// if (frameCount) numY = ~~random(2, 5);
	layers = Array(NUM_LAYERS); for (let i = 0; i < layers.length; i++) layers[i] = new Grid(numX, numY, () => []);
	masks = new Grid(numX, numY, () => []); 
	S = ~~min(width/numX, height/numY);
	S -= S/8;
	offX = (width - (S*numX)) / 2;
	offY = (height - (S*numY)) / 2;
	FG = color("deeppink");
	BG = color(4, 4, 12);
	background(BG);
	loop();
}

function draw() {
	translate(offX, offY);

	for (let y = 0; y < S * numY; y += S) {		
		for (let x = 0; x < S * numX; x += S) {
			const num = 1; // ~~random(layers.length-1, layers.length+1);
			const types = getDistinctArr(num, [0, 1, 2, 3]);
			for (let i = 0; i < types.length; i++) {
				if (i === layers.length) break;
				const typ = types[i];
				// grid.setVal(x/S, y/S, typ);
				drawShape(x, y, S * 0.9, typ, i);
			}
		}
	}

	// noLoop() removed for animation
}

function getDistinctArr(num, source) {
	let arr = [], entropy = [];
	for (let i = 0; i < num; i++) {
		if (!entropy.length) entropy = [...source];
		var idx = ~~random(entropy.length);
		arr.push(entropy[idx]);
		entropy.splice(idx, 1);
	}
	return arr;
}

function drawShape(x, y, s, typ = null, idx = null) {
	let r = s / 2; // 2.25
	let edges = [1*r, 1*r, 1*r, 1*r];
	for (let i = 0; i < 2; i++) {
		var idx = ~~random(edges.length)
		edges[idx] = 0;
	}
	fill(random(100, 300), random(500, 150), random(100, 200));
	rect(x, y, s, s, ...edges);
}

